"use agent";

import { env } from "cloudflare:workers";
import { useInitialData, useModel } from "@flue/runtime";
import * as v from "valibot";
import { AGENT_DURABILITY, useExtractTool } from "./extract-tool.ts";
import { authorInstruction } from "./prompts.ts";

export const AuthorInitialData = v.object({
  html: v.string(),
});

export function Author() {
  // Flue defaults the thinking level to "medium"; asking for none is what routes
  // the request through the model entry's "off" mapping, the cheapest effort this
  // endpoint accepts. Thinking cannot be disabled outright here.
  useModel(env.agentModel, { thinkingLevel: "off" });
  const { html } = useInitialData<v.InferOutput<typeof AuthorInitialData>>();
  useExtractTool(html);
  return authorInstruction(env.agentMaxTurns, html);
}

Author.initialData = AuthorInitialData;
Author.durability = AGENT_DURABILITY;
import { env } from "cloudflare:workers";
import { useTool } from "@flue/runtime";
import * as v from "valibot";
import { runRecipe } from "../runtime/run.ts";

export const AGENT_DURABILITY = { maxAttempts: 5, timeoutMs: 1_800_000 };

export function useExtractTool(html: string): void {
  useTool({
    name: "extract",
    description:
      "Run a candidate recipe against the article and return its extraction result or its validation report.",
    input: v.object({ recipe: v.string() }),
    output: undefined,
    async run({ data }) {
      return { output: await runRecipe(env, data.recipe, html) };
    },
  });
}
import { init } from "@flue/runtime";
import type * as v from "valibot";
import { Author, type AuthorInitialData } from "./author.ts";
import { Revisor, type RevisorInitialData } from "./revisor.ts";

export type AgentKind = "author" | "revision";

export interface AgentDispatchReceipt {
  submissionId: string;
  acceptedAt: string;
  uid: string;
}

export interface AgentInitialData {
  html: string;
  recipe?: string;
}

function agentFor(kind: AgentKind) {
  return kind === "author" ? Author : Revisor;
}

function initialDataFor(kind: AgentKind, data: AgentInitialData): unknown {
  if (kind === "author") {
    return { html: data.html } satisfies v.InferOutput<typeof AuthorInitialData>;
  }
  return { html: data.html, recipe: data.recipe ?? "" } satisfies v.InferOutput<
    typeof RevisorInitialData
  >;
}

export async function dispatchAgent(
  kind: AgentKind,
  conversationId: string,
  message: string,
  initialData: AgentInitialData,
): Promise<AgentDispatchReceipt> {
  const handle = init(agentFor(kind), { id: conversationId });
  return await handle.dispatch({ message, initialData: initialDataFor(kind, initialData) });
}

export async function readAgent(
  kind: AgentKind,
  conversationId: string,
  receipt: AgentDispatchReceipt,
): Promise<{ text: string }> {
  const handle = init(agentFor(kind), { id: conversationId });
  const reply = await handle.read(receipt);
  return { text: reply.text };
}

